// The Sunken Vault, a level for examples/level_walk.psh
//
// Brushes are convex solids; the space you walk through is what is left
// between them. Coordinates are in meters. A texture tiles at 40 texels per
// meter by default, so a 256-texel texture repeats every 6.4 m. Rooms are
// sized in multiples of 1.6 m.
//
//   tex   <index> <name>
//   start <x> <y> <z> <yaw degrees>
//   light <x> <y> <z> <radius> <brightness>
//   box   <x0> <y0> <z0> <x1> <y1> <z1> [keys]
//   ramp  <x0> <y0> <z0> <x1> <y1> <z1> <px|nx|pz|nz> [keys]
//   prism <cx> <cz> <radius> <y0> <y1> <sides> <rot degrees> [keys]
//   arch  <x|z> <a0> <a1> <c0> <c1> <ybase> <ytop> <segments> [keys]
//
// Keys: all= side= top= bottom= nx= px= ny= py= nz= pz= to place textures,
// light=<0..15> to force a light level instead of baking one, scale=<f> sets
// the texture density in texels per meter (default 40, so scale=20 makes a
// texture repeat over twice the span),
// fit to stretch a texture once across each face, flow to make it swim and
// burn at full brightness whatever is around it,
// turn to give the texture a quarter turn on the face.
//
// Nothing here is lit by hand except the fixtures themselves: every other
// surface takes its light from the lamps below, so the rooms go dark wherever
// the lamps do not reach.

tex  0 stone_blocks
tex  1 brick_tan
tex  2 stone_large
tex  3 floor_stone
tex  4 sandstone_brick
tex  5 rock_craggy
tex  6 lava
tex  7 lava_swirl
tex  8 metal_riveted
tex  9 floor_tread
tex 10 iron_brick
tex 11 light_bank
tex 12 light_square
tex 13 floor_checker
tex 14 brick_blue
tex 15 metal_bolted
tex 16 door_grate
tex 17 floor_dirt
tex 18 metal_dark
tex 19 crate_wood
tex 20 wood_dark
tex 21 rock_slate
tex 22 light_strip_red
tex 23 floor_gravel

start 0 1.4 -13 0

// ===========================================================================
// Entry crypt: interior x -4.8..4.8, z -17.6..-6.4, floor 0, ceiling 5.6
// ===========================================================================

box -6.4 -0.8 -19.2 6.4 0 -4.8 all=3
box -6.4 5.6 -19.2 6.4 6.4 -4.8 all=2
box -6.4 0 -19.2 6.4 5.6 -17.6 all=0

// West wall, with a torch niche cut into it at z -14..-12.4
box -6.4 0 -19.2 -4.8 5.6 -14 all=0
box -6.4 0 -12.4 -4.8 5.6 -4.8 all=0
box -6.4 0 -14 -4.8 2.4 -12.4 all=0
box -6.4 4 -14 -4.8 5.6 -12.4 all=0
box -6.4 2.4 -14 -5.6 4 -12.4 all=0 px=11 light=15 fit

// East wall, with the same niche mirrored
box 4.8 0 -19.2 6.4 5.6 -14 all=0
box 4.8 0 -12.4 6.4 5.6 -4.8 all=0
box 4.8 0 -14 6.4 2.4 -12.4 all=0
box 4.8 4 -14 6.4 5.6 -12.4 all=0
box 5.6 2.4 -14 6.4 4 -12.4 all=0 nx=11 light=15 fit

light -5.3 3.2 -13.2 8.5 1.0
light 5.3 3.2 -13.2 8.5 1.0

// South wall of the crypt, with an arched doorway at x -2.4..2.4
box -6.4 0 -6.4 -2.4 5.6 -4.8 all=0
box 2.4 0 -6.4 6.4 5.6 -4.8 all=0
box -2.4 5.6 -6.4 2.4 6.4 -4.8 all=0
arch z -6.4 -4.8 -2.4 2.4 3.6 5.6 5 all=4 bottom=4

// ===========================================================================
// Passage down to the vault: x -2.4..2.4, z -4.8..0, ceiling 5.6
// ===========================================================================

box -4 -0.8 -4.8 4 0 0 all=3
box -4 5.6 -4.8 4 6.4 0 all=2
box -4 0 -4.8 -2.4 5.6 0 all=1
box 2.4 0 -4.8 4 5.6 0 all=1

light 0 4.25 -2.4 6 0.45

// ===========================================================================
// The vault: interior x -14.4..14.4, z 0..32. The lava lake sits at y -4.4,
// the stone bridge crosses it at y 0, and the ceiling is up at 16.
// ===========================================================================

// The lake, and the ledges at either end of it
box -14.4 -6.4 3.2 14.4 -4.4 27.2 all=6 flow
box -14.4 -6.4 0 14.4 0 3.2 all=3 top=3 scale=20
box -14.4 -6.4 27.2 14.4 0 32 all=3 top=3 scale=20

// The bridge across the lake
box -2.4 -6.4 3.2 2.4 0 27.2 all=8 top=3 scale=20

// The ceiling is a gable running the length of the room: two slopes rising
// from the tops of the side walls at 10.4 to a ridge down the middle at 16,
// where the slab that caps the room sits on them. An arch of two segments is
// exactly that pair of slopes.
arch z 0 32 -14.4 14.4 10.4 16 2 all=2 bottom=2

// That cap, and the walls behind everything else
box -16 16 0 16 16.8 33.6 all=2
box -16 -6.4 0 -14.4 16 6.4 all=0
box -16 -6.4 10.4 -14.4 16 14 all=0
box -16 -6.4 18 -14.4 16 21.6 all=0
// This stretch of the west wall carries the way through to the monolith
// chamber. The opening sits at ledge level in the far corner of the room, so
// what you see from the bridge is a door in the corner rather than a stair
// standing out in the open; the climb is all on the far side of it.
box -16 -6.4 25.6 -14.4 16 27.2 all=0
box -16 -6.4 32 -14.4 16 33.6 all=0
box -16 -6.4 27.2 -14.4 0 32 all=0 top=3
box -16 5.6 27.2 -14.4 16 32 all=0
arch x -16 -14.4 27.2 32 3.6 5.6 4 all=4 bottom=4

box 14.4 -6.4 0 16 16 33.6 all=0

// North wall, with the arched way back to the passage
box -16 -6.4 -1.6 -2.4 16 0 all=0
box 2.4 -6.4 -1.6 16 16 0 all=0
box -2.4 5.6 -1.6 2.4 16 0 all=0
arch z -1.6 0 -2.4 2.4 3.6 5.6 5 all=4 bottom=4

// South wall, with the arched way on to the reliquary. The doorway needs its
// own floor: the wall pieces either side of it stop at the opening.
box -3.2 -2.4 32 3.2 0 33.6 all=3 top=3 scale=20
box -16 -6.4 32 -3.2 16 33.6 all=0
box 3.2 -6.4 32 16 16 33.6 all=0
box -3.2 7.2 32 3.2 16 33.6 all=0
arch z 32 33.6 -3.2 3.2 4.8 7.2 5 all=4 bottom=4

// --- Timber beams tying the roof across, one every 6.4 m ---
//
// They sit above the eaves, so each one runs out of one slope and into the
// other, and nothing below them is high enough to touch. `turn` lays the grain
// along the beam rather than across it.

box -14.4 11.4 2.7 14.4 12.6 3.7 all=20 turn
box -14.4 11.4 9.1 14.4 12.6 10.1 all=20 turn
box -14.4 11.4 15.5 14.4 12.6 16.5 all=20 turn
box -14.4 11.4 21.9 14.4 12.6 22.9 all=20 turn
box -14.4 11.4 28.3 14.4 12.6 29.3 all=20 turn

// --- The west arcade: three lamps in arched recesses ---
//
// Each one is a pocket cut 0.8 m deep into the wall: the wall below and
// above it, the back of the pocket, the lamp mounted on that back, and a
// faceted arch
// across the mouth. Nothing protrudes into the room.

box -16 -6.4 6.4 -14.4 0 10.4 all=0
box -16 5.6 6.4 -14.4 16 10.4 all=0
box -16 0 6.4 -15.2 5.6 10.4 all=1
box -15.2 1.6 7.6 -15.1 4.4 9.2 all=0 px=11 light=15 fit
arch x -15.2 -14.4 6.4 10.4 4.4 5.6 4 all=4 bottom=4

box -16 -6.4 14 -14.4 0 18 all=0
box -16 5.6 14 -14.4 16 18 all=0
box -16 0 14 -15.2 5.6 18 all=1
box -15.2 1.6 15.2 -15.1 4.4 16.8 all=0 px=11 light=15 fit
arch x -15.2 -14.4 14 18 4.4 5.6 4 all=4 bottom=4

box -16 -6.4 21.6 -14.4 0 25.6 all=0
box -16 5.6 21.6 -14.4 16 25.6 all=0
box -16 0 21.6 -15.2 5.6 25.6 all=1
box -15.2 1.6 22.8 -15.1 4.4 24.4 all=0 px=11 light=15 fit
arch x -15.2 -14.4 21.6 25.6 4.4 5.6 4 all=4 bottom=4

light -14.8 3 8.4 9.5 1.0
light -14.8 3 16 9.5 1.0
light -14.8 3 23.6 9.5 1.0

// --- Buttresses along the west wall, angled where they meet it ---
//
// `nx` keeps the wall side at full height, so each one is deepest against the
// wall and slopes away as it comes out over the lava, which is the way a
// buttress carries a load

ramp -14.4 -4.4 4.5 -12.4 4.5 6.5 nx all=4
ramp -14.4 -4.4 12.1 -12.4 4.5 14.1 nx all=4
ramp -14.4 -4.4 19.7 -12.4 4.5 21.7 nx all=4

// --- The east side: a plinth, a ramp climbing it, and the gallery above ---

box 9.6 -6.4 27.2 14.4 0 32 all=0 top=3

// A slab under the ramp, so the foot of it has some thickness to it instead of
// tapering away to nothing where it meets the ledge
box 9.6 -0.75 12.8 14.4 0 27.2 all=0 scale=20
ramp 9.6 0 12.8 14.4 6.4 27.2 nz all=0 top=3 scale=20

box 9.6 -6.4 3.2 14.4 6.4 12.8 all=0 top=3 scale=20

// The parapet along the gallery, with a gap to see over
box 8.8 6.4 3.2 9.6 8 7.4 all=4
box 8.8 6.4 10.6 9.6 8 12.8 all=4
box 8.8 6.4 7.4 9.6 7.2 10.6 all=4

// Lamps set into the east wall above the gallery
box 14.2 8 6 14.4 9.6 7.4 all=1 nx=12 light=15 fit
box 14.2 8 9.8 14.4 9.6 11.2 all=1 nx=12 light=15 fit
light 13.8 8.75 6.7 7.5 1.0
light 13.8 8.75 10.5 7.5 1.0

// A crate or two left on the gallery
box 10.5 6.4 4.5 12.9 8.8 6.9 all=19 fit
box 10.8 8.8 5.1 12.6 10.6 6.7 all=19 fit

// --- What the lava throws up into the room ---
//
// These sit in the open air over the lake, clear of the bridge pier at x
// -2.4..2.4 and of the east plinth at x 9.6: a lamp inside either one is walled
// off from the room and lights nothing.
//
// The lake runs z 3.2..27.2, so they are spaced about its middle at 15.2. A
// lamp nearer one end than the other lights that end's ledge harder, and since
// the two ledges face each other across the room the difference is there to be
// compared.

light -7.2 -3.25 8 14 0.44
light 7.2 -3.25 8 14 0.44
light -7.2 -3.25 15.2 14 0.44
light 7.2 -3.25 15.2 14 0.44
light -7.2 -3.25 22.4 14 0.44
light 7.2 -3.25 22.4 14 0.44
light -7.5 -3.25 11.6 12 0.34
light 7.5 -3.25 11.6 12 0.34
light -7.5 -3.25 18.8 12 0.34
light 7.5 -3.25 18.8 12 0.34

// The glow the lake throws up onto the bridge and the ledges. These sit above
// the deck on purpose: a floor takes nothing from a lamp underneath it. They
// stand almost on top of the deck, so what they mostly light is the deck, and
// they are the one thing that decides how bright it reads.
light 0 2.25 7.5 14 0.42
light 0 2.25 15 14 0.42
light 0 2.25 22.5 14 0.42

// High fill under the eaves. Mirrored: a single lamp to one side at each end
// leans the whole bridge that way, and the lean reads as a mistake because
// nothing up there is visible to explain it.
light -7.5 10.5 12 15.5 0.13
light 7.5 10.5 12 15.5 0.13
light -7.5 10.5 20.5 15.5 0.13
light 7.5 10.5 20.5 15.5 0.13
light -6.5 3 2.75 9.5 0.46
light 6.5 3 2.75 9.5 0.46
light -6.5 3 29.5 9.5 0.46
light 6.5 3 29.5 9.5 0.46

// ===========================================================================
// The reliquary: interior x -6.4..6.4, z 33.6..44.8, ceiling 7.2. A sunken
// pool of lava in the middle of the floor lights the room from below.
// ===========================================================================

box -8 7.2 33.6 8 8 46.4 all=2
box -8 0 33.6 -6.4 7.2 46.4 all=14
box 6.4 0 33.6 8 7.2 46.4 all=14
box -8 0 44.8 8 7.2 46.4 all=14

// The floor, in four pieces around the pool
box -8 -2.4 33.6 8 0 37.6 all=13
box -8 -2.4 42.4 8 0 46.4 all=13
box -8 -2.4 37.6 -3.2 0 42.4 all=13
box 3.2 -2.4 37.6 8 0 42.4 all=13

// The pool itself, and the rough rock it has eaten into. The surface rides
// the wave, which takes it a WAVE_AMP down each way, so it sits that much
// above the underside of the floor rather than flush with it: level with it,
// the down-swing would pull the lava clear of the rim and open a gap all the
// way round.
box -3.2 -4 37.6 3.2 -2 42.4 all=7 flow
box -3.2 -4.2 37.4 3.2 -4 42.6 all=5

// An eight-sided pedestal standing in the pool
prism 0 40 1.8 -2.4 2.4 8 22.5 all=4 top=4

light 0 -1 40 11.5 0.85
light 0 5.25 35.75 6.5 0.3

// Torch niches either side of the door back out
box -6.4 2.4 34 -5.6 4 35.4 all=14 px=11 light=15 fit
box 5.6 2.4 34 6.4 4 35.4 all=14 nx=11 light=15 fit
light -5.3 3.2 34.7 8 0.9
light 5.3 3.2 34.7 8 0.9

// ===========================================================================
// The monolith chamber: interior x -84.8..-33.6, z 4..55.2, floor 6.4,
// ceiling 57.6. A 51.2 m cube, hung off the west wall of the vault and reached
// from the far corner of the ledge behind the lava: a low corridor, then a
// stair climbing 6.4 m in a shaft that opens out above you.
//
// The crosses stop 9.6 m short of the ceiling, which is a good deal more than
// they stand clear of the floor: the roof wants dark above them rather than
// the tops of the arms crowding it.
//
// The door is left the size it always was, so the room opens out all at once
// as you step through it rather than being announced by its entrance.
//
// The room is lit only by what the crosses give off, which is little, by the
// well in the roof, and by one lamp inside the door. Everything else is meant
// to be lost in the dark.
// ===========================================================================

// --- The corridor in from the ledge, and the stair shaft beyond it ---
//
// The corridor is as wide as the ledge it leaves and the height of a door. The
// shaft it runs into is wider again and more than twice as tall, so the space
// opens out around you and over your head as the stair starts to climb.

box -19.2 -1.6 27.2 -16 0 32 all=0 top=3
box -19.2 5.6 27.2 -16 14.4 32 all=10
box -19.2 -1.6 25.6 -16 14.4 27.2 all=10
box -19.2 -1.6 32 -16 14.4 33.6 all=10

box -32 -1.6 24.8 -19.2 12.8 26.4 all=10
box -32 -1.6 32.8 -19.2 12.8 34.4 all=10
box -32 12.8 26.4 -19.2 14.4 32.8 all=10

// Sixteen steps of 0.4 m, climbing west from x -19.2 to the sill at -32.
// Each one carries down to the underside of the corridor floor, so the
// flight is solid.

box -20 -1.6 26.4 -19.2 0.4 32.8 all=0 top=3
box -20.8 -1.6 26.4 -20 0.8 32.8 all=0 top=3
box -21.6 -1.6 26.4 -20.8 1.2 32.8 all=0 top=3
box -22.4 -1.6 26.4 -21.6 1.6 32.8 all=0 top=3
box -23.2 -1.6 26.4 -22.4 2 32.8 all=0 top=3
box -24 -1.6 26.4 -23.2 2.4 32.8 all=0 top=3
box -24.8 -1.6 26.4 -24 2.8 32.8 all=0 top=3
box -25.6 -1.6 26.4 -24.8 3.2 32.8 all=0 top=3
box -26.4 -1.6 26.4 -25.6 3.6 32.8 all=0 top=3
box -27.2 -1.6 26.4 -26.4 4 32.8 all=0 top=3
box -28 -1.6 26.4 -27.2 4.4 32.8 all=0 top=3
box -28.8 -1.6 26.4 -28 4.8 32.8 all=0 top=3
box -29.6 -1.6 26.4 -28.8 5.2 32.8 all=0 top=3
box -30.4 -1.6 26.4 -29.6 5.6 32.8 all=0 top=3
box -31.2 -1.6 26.4 -30.4 6 32.8 all=0 top=3
box -32 -1.6 26.4 -31.2 6.4 32.8 all=0 top=3

// --- Shell ---

box -86.4 4.8 2.4 -32 6.4 56.8 all=10 top=13

box -33.6 4.8 2.4 -32 59.2 26.4 all=10
box -33.6 4.8 32.8 -32 59.2 56.8 all=10
box -33.6 12 26.4 -32 59.2 32.8 all=10
arch x -33.6 -32 26.4 32.8 10 12 4 all=4 bottom=4

// --- The three crosses ---
//
// Each of the west, north and south walls is built in two layers: a back
// plate, and a front layer 0.8 m proud of it laid out as eight pieces around
// a cross shaped void. The upright stands 35.2 m and the bar reaches 25.6 m
// across, both cut 6.4 m thick, so what shows is a thin figure drawn on a
// broad wall rather than a blocky one. The bar sits a little over a quarter
// of the way up the
// upright rather than the same distance down from the top, which turns the
// cross over.
//
// The bar is placed in whole lozenge rows. A row is 0.8 m -- a quarter of the
// 3.2 m a panel fits -- so the bar can only be moved by multiples of 0.8 m
// without its rows falling out of step with the upright's.
//
// The void is filled with lamp panels laid on the back plate, so each cross
// reads as a slot of red light rather than a shadow. Those panels are cut into
// 3.2 m squares, one per texture, and each is marked `fit`: the lamp texture is
// 128 texels across and lays its eight lozenges out on a 64 by 32 texel grid
// inside that, so a panel whose edges miss those lines slices the lozenges at
// its ends. A limb is two panels across at this size, and the void is filled
// two columns wide rather than one. The room is centred on z 29.6 and x -59.2,
// neither of which the grid divides, so tiling by world position cannot be
// made to land -- `fit` maps one whole copy across each square instead and
// puts the cut where the panels already end.
//
// The upright and the arms are cut as separate squares that meet rather than
// overlap, so no two lamp faces are coplanar.

// West wall
box -86.4 4.8 2.4 -85.6 59.2 56.8 all=10

box -85.6 6.4 4 -84.8 12.8 55.2 all=10
box -85.6 48 4 -84.8 57.6 55.2 all=10
box -85.6 12.8 4 -84.8 19.2 26.4 all=10
box -85.6 12.8 32.8 -84.8 19.2 55.2 all=10
box -85.6 19.2 4 -84.8 25.6 16.8 all=10
box -85.6 19.2 42.4 -84.8 25.6 55.2 all=10
box -85.6 25.6 4 -84.8 48 26.4 all=10
box -85.6 25.6 32.8 -84.8 48 55.2 all=10

box -85.6 12.8 26.4 -85.5 16 29.6 all=10 px=22 light=15 fit
box -85.6 16 26.4 -85.5 19.2 29.6 all=10 px=22 light=15 fit
box -85.6 19.2 26.4 -85.5 22.4 29.6 all=10 px=22 light=15 fit
box -85.6 22.4 26.4 -85.5 25.6 29.6 all=10 px=22 light=15 fit
box -85.6 25.6 26.4 -85.5 28.8 29.6 all=10 px=22 light=15 fit
box -85.6 28.8 26.4 -85.5 32 29.6 all=10 px=22 light=15 fit
box -85.6 32 26.4 -85.5 35.2 29.6 all=10 px=22 light=15 fit
box -85.6 35.2 26.4 -85.5 38.4 29.6 all=10 px=22 light=15 fit
box -85.6 38.4 26.4 -85.5 41.6 29.6 all=10 px=22 light=15 fit
box -85.6 41.6 26.4 -85.5 44.8 29.6 all=10 px=22 light=15 fit
box -85.6 44.8 26.4 -85.5 48 29.6 all=10 px=22 light=15 fit

box -85.6 12.8 29.6 -85.5 16 32.8 all=10 px=22 light=15 fit
box -85.6 16 29.6 -85.5 19.2 32.8 all=10 px=22 light=15 fit
box -85.6 19.2 29.6 -85.5 22.4 32.8 all=10 px=22 light=15 fit
box -85.6 22.4 29.6 -85.5 25.6 32.8 all=10 px=22 light=15 fit
box -85.6 25.6 29.6 -85.5 28.8 32.8 all=10 px=22 light=15 fit
box -85.6 28.8 29.6 -85.5 32 32.8 all=10 px=22 light=15 fit
box -85.6 32 29.6 -85.5 35.2 32.8 all=10 px=22 light=15 fit
box -85.6 35.2 29.6 -85.5 38.4 32.8 all=10 px=22 light=15 fit
box -85.6 38.4 29.6 -85.5 41.6 32.8 all=10 px=22 light=15 fit
box -85.6 41.6 29.6 -85.5 44.8 32.8 all=10 px=22 light=15 fit
box -85.6 44.8 29.6 -85.5 48 32.8 all=10 px=22 light=15 fit

box -85.6 19.2 16.8 -85.5 22.4 20 all=10 px=22 light=15 fit
box -85.6 19.2 20 -85.5 22.4 23.2 all=10 px=22 light=15 fit
box -85.6 19.2 23.2 -85.5 22.4 26.4 all=10 px=22 light=15 fit
box -85.6 19.2 32.8 -85.5 22.4 36 all=10 px=22 light=15 fit
box -85.6 19.2 36 -85.5 22.4 39.2 all=10 px=22 light=15 fit
box -85.6 19.2 39.2 -85.5 22.4 42.4 all=10 px=22 light=15 fit

box -85.6 22.4 16.8 -85.5 25.6 20 all=10 px=22 light=15 fit
box -85.6 22.4 20 -85.5 25.6 23.2 all=10 px=22 light=15 fit
box -85.6 22.4 23.2 -85.5 25.6 26.4 all=10 px=22 light=15 fit
box -85.6 22.4 32.8 -85.5 25.6 36 all=10 px=22 light=15 fit
box -85.6 22.4 36 -85.5 25.6 39.2 all=10 px=22 light=15 fit
box -85.6 22.4 39.2 -85.5 25.6 42.4 all=10 px=22 light=15 fit

// North wall
box -86.4 4.8 2.4 -32 59.2 3.2 all=10

box -84.8 6.4 3.2 -33.6 12.8 4 all=10
box -84.8 48 3.2 -33.6 57.6 4 all=10
box -84.8 12.8 3.2 -62.4 19.2 4 all=10
box -56 12.8 3.2 -33.6 19.2 4 all=10
box -84.8 19.2 3.2 -72 25.6 4 all=10
box -46.4 19.2 3.2 -33.6 25.6 4 all=10
box -84.8 25.6 3.2 -62.4 48 4 all=10
box -56 25.6 3.2 -33.6 48 4 all=10

box -62.4 12.8 3.2 -59.2 16 3.3 all=10 pz=22 light=15 fit
box -62.4 16 3.2 -59.2 19.2 3.3 all=10 pz=22 light=15 fit
box -62.4 19.2 3.2 -59.2 22.4 3.3 all=10 pz=22 light=15 fit
box -62.4 22.4 3.2 -59.2 25.6 3.3 all=10 pz=22 light=15 fit
box -62.4 25.6 3.2 -59.2 28.8 3.3 all=10 pz=22 light=15 fit
box -62.4 28.8 3.2 -59.2 32 3.3 all=10 pz=22 light=15 fit
